 private WorkspaceView workspaceView(JourneyMarketingWorkspace w){JourneyMarketingGenerationRun run=generationRuns.findTopByWorkspaceIdAndDeletedAtIsNullOrderByCreatedAtDescIdDesc(w.getId()).orElse(null);List<AssetView> list=assetVersions.findCurrentByWorkspace(w.getId()).stream().map(v->new AssetView(v.getAsset().getId(),v.getId(),v.getAsset().getAssetType().name(),v.getAsset().getDisplayOrder(),v.getTitle(),parse(v.getContentJson()),v.getAsset().isSelected(),v.getVersionNumber())).toList();return new WorkspaceView(w.getId(),w.getState().name(),w.getConceptVersion().getId(),w.getConceptVersion().getName(),run==null?null:parse(run.getResultJson()),list,w.getError(),w.getCompletedAt());}
